    add.answer(2, "\r");
    add.answer(3, "\r");
    add.after("Changelog summary", 1, "Fix\r");
    add.after("Write this changeset?", 1, "\r");
    assert_eq!(add.exit_code(), Some(0), "{}", add.screen());
    assert_eq!(changesets(dir.path()), ["---\n42: patch\n---\n\nFix\n"]);
}

