class Session:
    def __init__(self,root,args):
        self.master,slave=pty.openpty();fcntl.ioctl(slave,termios.TIOCSWINSZ,struct.pack('HHHH',30,160,0,0))
        env=dict(os.environ,TERM='xterm-256color',NO_COLOR='1');env.pop('EDITOR',None);env.pop('VISUAL',None)
        self.p=subprocess.Popen([BIN,'--cwd',str(root),*args],stdin=slave,stdout=slave,stderr=slave,env=env,start_new_session=True)
        os.close(slave);self.raw=b'';self.mark=0
    def plain(self):return ANSI.sub(b'',self.raw).decode('utf8','replace')
    def read(self):
        if select.select([self.master],[],[],.05)[0]:
            try:self.raw+=os.read(self.master,65536)
            except OSError:pass
    def wait(self,text):
        deadline=time.monotonic()+12
        while text not in ANSI.sub(b'',self.raw[self.mark:]).decode('utf8','replace'):
            self.read()
            if self.p.poll() is not None:raise RuntimeError('exit waiting '+repr(text)+': '+self.plain())
            if time.monotonic()>deadline:raise RuntimeError('timeout waiting '+repr(text)+': '+self.plain())
        time.sleep(.12);self.read()
    def send(self,text):self.mark=len(self.raw);os.write(self.master,text.encode())
    def finish(self,label):
        deadline=time.monotonic()+12
