            return {'names':names,'answer':answer,'exit':code,'rejected':True,'files':list(map(str,root.glob('.changeset/*.md')))}
        s.wait('Your answer');s.send('\n');s.wait('Your answer');s.send('\n');s.wait('Write this changeset?')
